// The default 2 GB Gradle heap runs out of memory in D8 (dexing) on this project.
// android/ is generated by prebuild, so set it here instead of editing gradle.properties.
const { withGradleProperties } = require('expo/config-plugins')

const JVM_ARGS = '-Xmx4096m -XX:MaxMetaspaceSize=1024m'

module.exports = function withGradleHeap(config) {
  return withGradleProperties(config, (cfg) => {
    cfg.modResults = cfg.modResults.filter((p) => !(p.type === 'property' && p.key === 'org.gradle.jvmargs'))
    cfg.modResults.push({ type: 'property', key: 'org.gradle.jvmargs', value: JVM_ARGS })
    return cfg
  })
}
